(function(){const e=window.matchMedia("(prefers-reduced-motion: reduce)").matches;if(e)return;const t=document.querySelectorAll("[data-logo-carousel-track]:not([data-animated])");t.forEach(function(e){if(!e.scrollWidth)return;const n=Number(e.dataset.logoCarouselSpeed||50);e.setAttribute("data-animated","true");const t=e.scrollWidth/2,s=t/n*1e3;e.animate([{transform:"translateX(0)"},{transform:"translateX(-"+t+"px)"}],{duration:s,iterations:1/0,easing:"linear"})})})()